class ComputeScalarCriticalPoints(Node):
    def __init__(self, parent_node_id : str, which_points : str):
        if correctness_checks_on():
            if which_points not in ['all critical points (mins+maxes+saddles)', 'minima', 'maxima', 'saddles', 
                                    'all contour tree vertices (mins+maxes+saddles)', 'contour tree saddles']:
                raise Exception(f"which_points has value {which_points} but must be one of 'all critical points (mins+maxes+saddles)', 'minima', 'maxima', 'saddles'"\
                                " 'all contour tree vertices (mins+maxes+saddles)', or 'contour tree saddles")

        super().__init__(parent_node_id, types.Scalar, types.ScalarCriticalPoints, locals())

        self.which_points = which_points

    @classmethod
    def guardrails(cls):
        return [simplification_guardrail, piecewise_linear_guardrail]

    @classmethod
    def additional_tool_checks():
        pass

    @classmethod
    def chat_description(cls):
        return "queued computing scalar field critical points"

    @classmethod
    def description(cls):
        return 'Computes the piecewise-linear critical points of a scalar field.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar corresponding to the scalar field '
                           'whose critical points we are computing.',
         'which_points': 'A string specifying which critical points should be computed. '
                         "Options are: 'all critical points (mins+maxes+saddles)', 'minima', 'maxima', 'saddles', 'all contour tree vertices (mins+maxes+saddles)'"
                         ", or 'contour tree saddles'. If the data is 2D, 'all contour tree vertices (mins+maxes+saddles)' "
                         "and 'all critical points (mins+maxes+saddles)' will give the same result. Do not proceed "
                         'with any computations unless the user explicitly specifies a value '
                         'for this parameter.'}

    def _evaluation_logic(self, parent_data, time_step):

        if self.which_points == 'all contour tree vertices (mins+maxes+saddles)' or self.which_points == 'contour tree saddles':
            points = ttk.TTKContourTree(Input=parent_data.data)
            points.ScalarField = ['POINTS', 'Scalars_']
            points.InputOffsetField = ['POINTS', 'Scalars_']

            if self.which_points == 'all contour tree vertices (mins+maxes+saddles)':
                return types.ScalarCriticalPoints(points)

            threshold = Threshold(Input=points)
            threshold.Scalars = ['POINTS', 'CriticalType']
            threshold.LowerThreshold = 1
            threshold.UpperThreshold = 2

            return types.ScalarCriticalPoints(threshold)

        else:

            points = ttk.TTKScalarFieldCriticalPoints(Input=parent_data.data)
            points.ScalarField = ['POINTS', 'Scalars_']
            points.InputOffsetField = ['POINTS', 'Scalars_']

            if self.which_points == 'all critical points (mins+maxes+saddles)':
                return types.ScalarCriticalPoints(points)

            threshold_values = {"minima" : (0,0), "saddles" : (1,2), "maxima" : (3,3)}[self.which_points]

            threshold = Threshold(Input=points)
            threshold.Scalars = ['POINTS', 'CriticalType']
            threshold.LowerThreshold = threshold_values[0]
            threshold.UpperThreshold = threshold_values[1]

            return types.ScalarCriticalPoints(threshold)

    @classmethod
    def mandatory_parameters(cls):
        return ["which_points"]

